import {
  IsNotEmpty,
  IsOptional,
  IsString,
  IsUUID,
  Length,
} from 'class-validator';

export class CreateMainAccountDto {
  @IsUUID()
  companyId: string;

  @IsUUID()
  accountTypeId: string;

  @IsUUID()
  balanceSheetId: string;

  @IsUUID()
  accountSubtypeId: string;

  @IsString()
  @IsNotEmpty()
  @Length(1, 150)
  description: string;

  @IsOptional()
  @IsString()
  @Length(1, 50)
  shortName?: string;

  // Rejected by the service: main account codes are generated by the backend.
  @IsOptional()
  @IsString()
  mainCode?: string;
}
